from html import escape

def p(text): return '<p>'+text+'</p>'
def h(text): return '<h2>'+text+'</h2>'
def ul(items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def table(headers, rows):
 return '<div class="guide-table" tabindex="0" role="region" aria-label="'+escape(' / '.join(headers))+'"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+x+'</th>') if i==0 else '<td>'+x+'</td>' for i,x in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def link(url,text): return '<a href="'+url+'">'+text+'</a>'

